const express = require('express');
const bodyParser = require('body-parser');
const path = require('path');
const fs = require('fs');
const { exec } = require('child_process');

const app = express();
app.use(bodyParser.json());

const sfProjectPath = 'C:\\Users\\safab\\OneDrive\\Desktop\\SalesForce\\sfdxTraining';

function deployAllApexClasses(orgAlias, callback) {
  const outputFolderPath = path.join(__dirname, orgAlias); // Folder path to save deployed classes

  // Ensure the output folder exists before proceeding
  fs.mkdir(outputFolderPath, { recursive: true }, (error) => {
    if (error) {
      console.error(`Failed to create output directory: ${error.message}`);
      callback({ error: 'Failed to create output directory' });
      return;
    }

    // Change working directory to the Salesforce project directory
    process.chdir(sfProjectPath);

    const command = `sfdx force:mdapi:deploy -d "${outputFolderPath}" -u ${orgAlias} -w 10 --json`;

    exec(command, (error, stdout, stderr) => {
      if (error) {
        console.error(`exec error: ${error}`);
        console.error(`stderr: ${stderr}`);
        callback({
          error: 'Failed to deploy Apex classes',
          details: stderr
        });
        return;
      }

      try {
        const result = JSON.parse(stdout);
        if (result.status === 0) {
          const deployedFiles = result.result.details.componentSuccesses;
          const apexClasses = deployedFiles.filter(file => file.componentType === 'ApexClass').map(file => ({
            fullName: file.fullName,
            content: file.fileName
          }));
          console.log('Deployed Apex classes:', apexClasses);

          // Save deployment details to a file
          const detailsFilePath = path.join(outputFolderPath, 'deploymentDetails.json');
          fs.writeFile(detailsFilePath, JSON.stringify(apexClasses, null, 2), 'utf8', (err) => {
            if (err) {
              console.error(`Failed to write deployment details: ${err}`);
            } else {
              console.log(`Saved deployment details to ${detailsFilePath}`);
            }
          });

          callback(null, apexClasses);
        } else {
          console.error(`Failed to deploy Apex classes: ${result.message}`);
          callback({
            error: 'Failed to deploy Apex classes',
            details: result.message
          });
        }
      } catch (parseError) {
        console.error(`Error parsing output: ${parseError}`);
        callback({
          error: 'Failed to deploy Apex classes',
          details: stdout
        });
      }
    });
  });
}

app.get('/deploy', (req, res) => {
  const orgAlias = req.query.orgAlias;
  deployAllApexClasses(orgAlias, (error, result) => {
    if (error) {
      res.status(500).json(error);
    } else {
      res.status(200).json(result);
    }
  });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

module.exports = deployAllApexClasses;
